-- Clientes da lista + usuário do ÚLTIMO atendimento (tabela `contato`) de cada um.
-- Clientes sem nenhum atendimento aparecem com usuario_id/usuario_nome = NULL.

SELECT
  c.id                                   AS cliente_id,
  c.nome                                 AS cliente_nome,
  u.id                                   AS ultimo_atendimento_usuario_id,
  u.nome                                 AS ultimo_atendimento_usuario_nome,
  COALESCE(ct.inicio, ct.createdAt)      AS ultimo_atendimento_data,
  ct.id                                  AS ultimo_atendimento_id
FROM cliente c
LEFT JOIN contato ct
  ON ct.id = (
    SELECT ct2.id
    FROM contato ct2
    WHERE ct2.clienteId = c.id
      AND ct2.deletedAt IS NULL
    ORDER BY COALESCE(ct2.inicio, ct2.createdAt) DESC, ct2.id DESC
    LIMIT 1
  )
LEFT JOIN usuario u
  ON u.id = ct.usuarioId
WHERE c.id IN (
  216074046464, 702839609344, 702839609348, 702839609364, 702839609393,
  1095082937347, 1100946167841, 1515728381953, 2005393408001, 3372890115072,
